/* ============================================================
 * 背景层 - v3.1 新增
 * body 底色 + #chat 透明 + 暗纹叠加
 * ============================================================ */

body {
  background-color: #1d2021 !important;
}

/* 全屏暗色遮罩（聊天区域外） */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(29, 32, 33, 0.92);
  pointer-events: none;
  z-index: 0;
}

/* 暗纹叠加层（在遮罩之上，聊天区之下） */
body::after {
  content: "" !important;
  position: fixed !important;
  top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(177, 98, 134, 0.008) 35px, rgba(177, 98, 134, 0.008) 70px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(177, 98, 134, 0.008) 35px, rgba(177, 98, 134, 0.008) 70px) !important;
  pointer-events: none !important;
  z-index: 0 !important;
}

/* #chat 用 JSON 字段的 chat_tint_color（已改为 0.75 透明） */
/* 消息背景透明，让 chat_tint 透过来 */
.mes {
  background-color: transparent !important;
}

