/* 删除消息模式：勾选框绝对定位，不挤压名字/计数器布局 */
.mes .for_checkbox {
  position: absolute !important;
  top: 6px !important;
  right: 6px !important;
  width: auto !important;
  height: auto !important;
  z-index: 30 !important;
  pointer-events: none !important;
}
.mes input[type="checkbox"].del_checkbox {
  position: absolute !important;
  top: 6px !important;
  right: 6px !important;
  margin: 0 !important;
  z-index: 31 !important;
  pointer-events: auto !important;
}

/* h3/h4 标题统一背景色/字号(与 drawer 内一致) */
h3.margin0,
h4.margin0,
.popup h3:not(dialog *) {
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, var(--SmartThemeBlurTintColor)) !important;
  font-size: calc(var(--mainFontSize) * 1.15) !important;
  font-weight: 600 !important;
  letter-spacing: 0.03em !important;
  line-height: 2 !important;
}

/* 用户人设/角色选中边框：只 Quote 色边,去光晕 */
.avatar-container.selected {
  border-color: var(--SmartThemeQuoteColor) !important;
  box-shadow: none !important;
}
/* 默认人设:圆角外框改主题Quote色 */
.avatar-container.default_persona .avatar {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--SmartThemeQuoteColor) !important;
}
.avatar-container.default_persona .avatar img {
  border-radius: inherit !important;
}
.bogus_folder_select:hover,
.character_select:hover,
.avatar-container:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, transparent) !important;
}

/* is_fav 收藏头像:圆角外框改主题Quote色 */
.character_select.is_fav .avatar,
.group_select.is_fav .avatar,
.group_member.is_fav .avatar,
.avatar.is_fav {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--SmartThemeQuoteColor) !important;
}
/* 收藏名字用主题 Quote 色 */
.character_select.is_fav .ch_name,
.group_select.is_fav .ch_name,
.group_member.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor) !important;
}



